<?php requirePermission('quotes');
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$customer=(int)($_POST['customer_id']??0);$valid=$_POST['valid_until']?:date('Y-m-d',strtotime('+7 days'));$notes=trim($_POST['notes']??'');$product=(int)($_POST['product_id']??0);$qty=max(1,(int)($_POST['quantity']??1));$discount=max(0,(float)($_POST['discount']??0));try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT id,name,price FROM products WHERE id=? AND active=1');$st->execute([$product]);$p=$st->fetch();if(!$p)throw new Exception('Produto inválido.');$subtotal=$p['price']*$qty;$discount=min($discount,$subtotal);$total=$subtotal-$discount;$pdo->prepare('INSERT INTO quotes(customer_id,user_id,subtotal,discount,total,valid_until,status,notes) VALUES(?,?,?,?,?,? ,"open",?)')->execute([$customer?:null,$_SESSION['user']['id'],$subtotal,$discount,$total,$valid,$notes]);$qid=$pdo->lastInsertId();$pdo->prepare('INSERT INTO quote_items(quote_id,product_id,quantity,unit_price,total) VALUES(?,?,?,?,?)')->execute([$qid,$p['id'],$qty,$p['price'],$subtotal]);$pdo->commit();flash('success','Orçamento #'.$qid.' criado.');redirect('index.php?page=quote_view&id='.$qid);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('index.php?page=quotes');}}
$customers=$pdo->query('SELECT id,name,document FROM customers ORDER BY name')->fetchAll();$products=$pdo->query('SELECT id,name,sku,price FROM products WHERE active=1 ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT q.*,c.name customer,u.name seller FROM quotes q LEFT JOIN customers c ON c.id=q.customer_id JOIN users u ON u.id=q.user_id ORDER BY q.id DESC LIMIT 50')->fetchAll();$title='Orçamentos';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Orçamentos</h1><p>Propostas sem movimentar estoque até a venda.</p></div></div><div class="grid two"><section class="panel"><h2>Novo orçamento</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Cliente<select name="customer_id"><option value="">Consumidor final</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?><?= $c['document']?' · '.e($c['document']):'' ?></option><?php endforeach;?></select></label><label>Produto<select name="product_id" required><option value="">Selecione...</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> · <?=e($p['sku'])?> · <?=money($p['price'])?></option><?php endforeach;?></select></label><div class="form-grid"><label>Quantidade<input name="quantity" type="number" min="1" value="1" required></label><label>Desconto R$<input name="discount" type="number" min="0" step="0.01" value="0"></label><label>Validade<input name="valid_until" type="date" value="<?=date('Y-m-d',strtotime('+7 days'))?>"></label></div><label>Observações<textarea name="notes"></textarea></label><button class="btn primary">Gerar orçamento</button></form></section><section class="panel"><h2>Últimos orçamentos</h2><table><thead><tr><th>#</th><th>Cliente</th><th>Total</th><th>Validade</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="index.php?page=quote_view&id=<?=$r['id']?>">#<?=$r['id']?></a></td><td><?=e($r['customer']?:'Consumidor final')?></td><td><?=money($r['total'])?></td><td><?=date('d/m/Y',strtotime($r['valid_until']))?></td><td><span class="badge <?=$r['status']==='open'?'ok':''?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></section></div><?php require __DIR__.'/../../includes/footer.php';?>
